{
  "name": "CRSF遥控器桥接接口",
  "name_en": "CRSF Remote Controller Bridge",
  "manufacturer": "Unitree",
  "description": "这是一类基于 CRSF 控制链路的手持遥控器/接收接口，用于把摇杆与开关输入传给机器人系统。在实验室中，它常用于对移动机器人或四足机器人进行人工遥操作、模式切换和基础运动控制。",
  "description_en": "This is a CRSF-based handheld remote controller and receiver interface used to pass stick and switch inputs into a robotic system. In laboratory use, it is commonly used for manual teleoperation, mode switching, and basic motion control of mobile robots or quadrupeds.",
  "tag_hints": [
    "CRSF radio control",
    "robot teleoperation",
    "joystick input",
    "remote controller",
    "quadruped robot control",
    "serial communication",
    "ROS Joy mapping"
  ],
  "actions": [
    {
      "action_name": "auto-start_serial",
      "description": "启动与 CRSF 遥控接收链路的串口通信。",
      "description_en": "Start serial communication with the CRSF remote control link."
    },
    {
      "action_name": "auto-serial_reader",
      "description": "读取来自 CRSF 遥控器的串口控制数据包。",
      "description_en": "Read serial control packets coming from the CRSF remote controller."
    },
    {
      "action_name": "auto-handle_crsf_packet",
      "description": "解析 CRSF 控制数据包并转换为摇杆与按键状态。",
      "description_en": "Decode a CRSF control packet and convert it into joystick axes and button states."
    },
    {
      "action_name": "auto-publish_joy",
      "description": "输出当前遥控器的摇杆与开关状态。",
      "description_en": "Publish the current stick and switch state of the remote controller."
    },
    {
      "action_name": "auto-destroy_node",
      "description": "关闭遥控器通信并清理连接资源。",
      "description_en": "Shut down the controller communication and clean up connection resources."
    }
  ]
}

